/* 3-sinf Tarbiya (2023). I–IV bo‘limlar */
window.T3 = window.T3 || [];
T3.push(
{id:"m1",n:"1-mavzu",t:"Vatanim haqida nimalarni bilaman?",b:1,
 map:{c:"Mening Vatanim",br:[
  {t:"Davlat ramzlari",e:"🇺🇿",k:["bayroq","gerb","madhiya"],x:"Bayroq, gerb va madhiya — davlatimiz ramzlari. Bino ustida bayroq tursa, bu davlat muassasasi bo‘ladi."},
  {t:"Pul birligi",e:"💵",k:["valyuta","qog‘oz pul","tanga"],x:"Deyarli har bir davlatning o‘z puli bor. Pulda mashhur insonlar, obidalar va tarixiy binolar tasvirlanadi."},
  {t:"Vatanparvarlik",e:"❤️",k:["Vatanga muhabbat","hurmat","himoya"],x:"Vatanni sevish, xalq qadriyati va madaniyatini hurmat qilish, yurtni himoya qilishga tayyor turish — vatanparvarlik."},
  {t:"Do‘pka voqeasi",e:"🧢",k:["naqshlar","sayohat","noyob"],x:"Do‘pka o‘zining kimligini bilishni istadi. Transformer-do‘ppi unga har birimiz noyob ekanimizni aytdi."},
  {t:"O‘z ildizingni bil",e:"🌳",k:["tug‘ilgan joy","tarix","faxrlanish"],x:"O‘zligingni bilib faxrlanish uchun tug‘ilgan joying tarixini va u nimasi bilan mashhurligini bilish kerak."}]},
 q:[
 {t:"m",q:"Quyidagilardan qaysi biri davlatimiz ramzi?",a:["Madhiya","Adras gazlamasi","Sport formasi","Maktab qo‘ng‘irog‘i"],e:"Bayroq, gerb va madhiya davlatimiz ramzlari hisoblanadi."},
 {t:"m",q:"Sport musobaqasida g‘olib sportchining davlati uchun nima qilinadi?",a:["Bayrog‘i ko‘tarilib, madhiyasi yangraydi","Shu davlatning puli hammaga ulashib chiqiladi","Shu davlatning xaritasi devorga chizib qo‘yiladi","Shu davlatning ertagi baland ovozda o‘qiladi"],e:"Qaysi davlat sportchisi g‘olib bo‘lsa, o‘sha davlat bayrog‘i ko‘tariladi va madhiyasi yangraydi."},
 {t:"m",q:"Bino ustida davlat bayrog‘ini ko‘rsangiz, bu nimani bildiradi?",a:["Bu davlat muassasasi","Bu oddiy yashash uyi","Bu kichik o‘yin maydoni","Bu shaxsiy tomorqa"],e:"Shahar yoki qishloqda bino ustida bayroq tursa, demak, bu davlat muassasasi."},
 {t:"m",q:"Davlatning pul birligi boshqacha qanday ataladi?",a:["Valyuta","Madhiya","Obida","An’ana"],e:"Deyarli har bir davlatning o‘z valyutasi, ya’ni pul birligi bor."},
 {t:"m",q:"Vatanparvarlikka qaysi ish misol bo‘ladi?",a:["Xalq madaniyatini hurmat qilish","Yurt tarixini bilishdan bosh tortish","Davlat ramzlariga mutlaqo e’tibor bermaslik","Yurt haqida hech narsa bilmaslikka urinish"],e:"Vatanga muhabbat, xalq qadriyati va madaniyatini hurmat qilish, yurtni himoya qilishga tayyorlik — vatanparvarlik."},
 {t:"m",q:"Do‘pka nega xafa edi?",a:["O‘zini xunuk, hech kimga qiziq emas deb o‘yladi","Do‘konda uni juda tez-tez kiyib ko‘rishayotgan edi","Transformer-do‘ppi u bilan urishib, ketib qolgan edi","Sayohatda yomg‘ir yog‘ib, uning rangi o‘chib ketgan edi"],e:"Do‘pka: meni hech kim kiyib ko‘rmayapti, naqshlarimni ham bilmayman, deb xafa bo‘ldi."},
 {t:"m",q:"«Noyob» degani nimani bildiradi?",a:["Boshqalarga o‘xshamaydigan","Hammadan yomonroq bo‘lgan","Hammadan ancha kattaroq bo‘lgan","Boshqalardan nusxa ko‘chiradigan"],e:"Noyob — boshqalarga o‘xshamaydigan degani. Har birimiz noyobmiz."},
 {t:"tf",q:"Har bir insonning o‘ziga xos xususiyati va iste’dodi bor.",a:true,e:"Transformer-do‘ppi aytganidek, har birimizning ajoyib xususiyatlarimiz va iste’dodimiz bor."},
 {t:"tf",q:"Tug‘ilgan joyimiz tarixini bilishimiz shart emas.",a:false,e:"Noto‘g‘ri. O‘zligini bilib faxrlanish uchun inson tug‘ilgan joyi tarixini bilishi lozim."},
 {t:"f",q:"Chet ellik o‘rtog‘ingizga O‘zbekiston haqida nimalarni aytib bergan bo‘lardingiz?",e:"Masalan: davlat ramzlari, tarixiy obidalar, milliy taomlar, do‘ppilar va naqshlar, mashhur insonlar."}]},
{id:"m2",n:"2-mavzu",t:"O‘zbekiston xalqi — Vatanimiz faxri",b:1,
 map:{c:"Vatanimiz faxri",br:[
  {t:"Olima Dilfuza",e:"🔬",k:["biolog","foydali mikroblar","toza mevalar"],x:"Olima Dilfuza Egamberdiyeva kashf etgan foydali mikroblar o‘simliklarning tez o‘sishiga yordam beradi."},
  {t:"Ilm va tillar",e:"📚",k:["ona tili","ingliz tili","“Nima uchun?”"],x:"Avval ona tilini mukammal bilib, keyin chet tillarni, ayniqsa ingliz tilini o‘rganish kerak."},
  {t:"Kasb tanlash",e:"🎯",k:["qiziqish","iste’dod","sevimli kasb"],x:"Inson eng ko‘p qiziqqan sohasini kasb qilsa va uni sevsa, hayoti mazmunli bo‘ladi."},
  {t:"Cho‘qqini zabt etgan",e:"🏔️",k:["Sergey Denisenko","Everest","bayroq"],x:"2021-yilda Sergey Denisenko Everest cho‘qqisiga O‘zbekiston bayrog‘ini o‘rnatdi."},
  {t:"San’at ustasi",e:"🎭",k:["Bahodir Yo‘ldoshev","rejissor","bayramlar"],x:"Bahodir Yo‘ldoshev — aktyor va mashhur rejissor. U yirik bayram va tadbirlarni sahnalashtirgan."}]},
 q:[
 {t:"m",q:"Olima Dilfuza Egamberdiyeva kashf etgan mikroblar nimaga yordam beradi?",a:["O‘simliklarning tez o‘sishiga","Dengizlarning tozalanishiga","Qadimiy binolarni ta’mirlashga","Sportchilarning tog‘ga chiqishiga"],e:"U kashf etgan foydali mikroblar o‘simliklarning tez o‘sishiga yordam beradi."},
 {t:"m",q:"Ekologik toza meva-sabzavotlarning tarkibida nima bo‘lmaydi?",a:["Zararli kimyoviy elementlar","Foydali oziq moddalar","Inson uchun kerakli vitaminlar","Toza va shirin tabiiy sharbat"],e:"Ularning tarkibida zararli kimyoviy elementlar yo‘q, shuning uchun bolalar sog‘lom bo‘ladi."},
 {t:"m",q:"Olimaning aytishicha, ona tilidan keyin qaysi tilni, ayniqsa, yaxshi o‘rganish kerak?",a:["Ingliz tilini","Yapon tilini","Qadimgi yunon tilini","Fransuz tilini"],e:"Ilm-fanning eng so‘nggi ma’lumotlari Internetda ingliz tilida berib boriladi."},
 {t:"m",q:"Olimaning fikricha, inson kasbni qanday tanlashi kerak?",a:["O‘zi eng ko‘p qiziqqan sohadan","Do‘sti nimani tanlasa, shundan","Eng oson va tez tugaydigan ishdan","Uyiga eng yaqin joylashgan ishdan"],e:"Inson eng ko‘p qaysi sohaga qiziqsa, o‘sha uning bir umrlik ishi bo‘lishi kerak."},
 {t:"m",q:"Olimaning aytishicha, insoniyatning global muammolarini nima hal qiladi?",a:["Ilm-fan","Boylik","Omad","Sayohat"],e:"Pandemiya, qurg‘oqchilik, iqlim o‘zgarishi kabi muammolarni hal qilish yo‘li — ilm-fan."},
 {t:"m",q:"Sergey Denisenko O‘zbekiston bayrog‘ini qayerga o‘rnatdi?",a:["Everest cho‘qqisiga","Qoratepa tog‘iga","Toshkent teleminorasiga","Oqsaroy peshtoqiga"],e:"2021-yil 1-iyunda u bayrog‘imizni 8849 metrlik Everest cho‘qqisiga o‘rnatdi."},
 {t:"m",q:"Bahodir Yo‘ldoshev kim?",a:["Teatr aktyori va rejissori","Tog‘ cho‘qqilarini zabt etuvchi","Biolog olim va ixtirochi","Palov haqida kitob yozgan oshpaz"],e:"Bahodir Yo‘ldoshev — teatr va kino aktyori, mashhur teatr rejissori."},
 {t:"tf",q:"Sergey Denisenkoga «O‘zbekiston iftixori» unvoni berilgan.",a:true,e:"Everestga bayrog‘imizni o‘rnatgani uchun unga shu unvon berildi."},
 {t:"tf",q:"Olimaning fikricha, inson faqat olim degan nom olish uchun o‘qiydi.",a:false,e:"Noto‘g‘ri. U ilm olish farz ekanini va ilmni insonlar foydasiga sarflash kerakligini aytgan."},
 {t:"f",q:"Kim bo‘lishni orzu qilasiz va bu orzuga yetish uchun nima qilasiz?",e:"Masalan: qiziqqan sohamni tanlayman, yaxshi o‘qiyman, tillarni o‘rganaman, iste’dodimni rivojlantiraman."}]},
{id:"m3",n:"3-mavzu",t:"Men yashayotgan olam",b:1,
 map:{c:"Atrofimdagi olam",br:[
  {t:"Atrofimizdagilar",e:"👨‍👩‍👧",k:["qarindoshlar","qo‘shnilar","do‘stlar"],x:"Atrofimizda qarindoshlar, qo‘shnilar, do‘stlar va sinfdoshlar yashaydi."},
  {t:"Turli millatlar",e:"🤝",k:["o‘zbek","qozoq","tojik"],x:"Ular orasida o‘zbek, qoraqalpoq, qozoq, tatar, rus, turkman, tojik, qirg‘iz va boshqa millat vakillari bor."},
  {t:"Aloqa",e:"📞",k:["xat","qo‘ng‘iroq","do‘stlar"],x:"Uzoqdagi do‘stlar bilan xat yozish yoki qo‘ng‘iroq qilish orqali aloqada bo‘lish mumkin."},
  {t:"Mehmon odobi",e:"🙏",k:["hurmat","minnatdorchilik","tartib"],x:"Chet elda biz mehmonmiz: mezbonlarni hurmat qilib, jamoat joylarida tartibga rioya qilamiz."},
  {t:"Sayohatga tayyorgarlik",e:"🧳",k:["salomlashish","urf-odat","qoidalar"],x:"Safardan oldin o‘sha xalq tilida salomlashish va rahmat aytishni, urf-odat va qoidalarni o‘rganish foydali."}]},
 q:[
 {t:"m",q:"Chet elga borganda biz u yerda kim bo‘lamiz?",a:["Mehmon","Mezbon","Rahbar","Nazoratchi"],e:"Chet elga borsak, u yerda mehmon ekanimizni unutmasligimiz kerak."},
 {t:"m",q:"Chet elda mezbonlarga qanday munosabatda bo‘lish kerak?",a:["Hurmat qilib, minnatdorchilik bildirish","Ularning qoidalarini kulgi qilib yurish","Yaratgan sharoitlarini sezmaslikka olish","Faqat o‘zimizning aytganimizni qildirish"],e:"Mezbonlarni hurmat qilib, yaratgan sharoitlari uchun minnatdorchilik bildirish lozim."},
 {t:"m",q:"Chet elga borishdan oldin o‘sha xalq tilida nimani o‘rganib olish juda yaxshi?",a:["Salomlashish va rahmat aytishni","Uzun ilmiy maqolalar yozishni","Barcha qadimiy dostonlarni yod olishni","Qiyin qonun matnlarini tarjima qilishni"],e:"Salomlashish, xayrlashish va rahmat aytishni o‘rganib olish juda zo‘r ish."},
 {t:"m",q:"Safardan oldin tildan tashqari yana nimalarni bilib qo‘yish kerak?",a:["U yurtning urf-odat va qoidalarini","U yurtdagi har bir odamning ismini","U yurtdagi barcha uylarning rangini","U yurtdagi har bir daraxtning yoshini"],e:"O‘sha yurtning urf-odatlari va tartib-qoidalarini ham bilib qo‘yish kerak."},
 {t:"m",q:"Jamoat joylarida o‘zimizni qanday tutishimiz kerak?",a:["Odob saqlab, qoidalarga rioya qilish","Baland ovozda baqirib, yugurib yurish","Xohlagan joyga chiqindi tashlab ketish","Navbatni buzib, hammadan oldinga o‘tish"],e:"Jamoat joylarida odob saqlab, tartib-qoidalarga rioya qilishimiz shart."},
 {t:"m",q:"Darslikda atrofimizda uchrashi mumkin deb qaysi millatlar sanalgan?",a:["Qoraqalpoq, qozoq va tatar","Yapon, braziliyalik va hind","Italyan, ispan va portugal","Shved, norveg va daniyalik"],e:"O‘zbek, qoraqalpoq, qozoq, tatar, rus, turkman, tojik, qirg‘iz va boshqalar sanalgan."},
 {t:"m",q:"Boshqa shaharda yashaydigan do‘stingiz bilan qanday gaplashib turish mumkin?",a:["Xat yozib yoki qo‘ng‘iroq qilib","Uni hech qachon eslamay yurib","Faqat u kelishini jim kutib","Rasmini daftarga yashirib qo‘yib"],e:"Darslikda xat yozish va qo‘ng‘iroq qilish aloqa vositasi sifatida tilga olingan."},
 {t:"tf",q:"Atrofimizda uzoq yurtlardan, masalan, Xitoy yoki Germaniyadan kelganlar ham bo‘lishi mumkin.",a:true,e:"Angliya, Fransiya, Germaniya, Xitoydan kelganlar ham bo‘lishi mumkin."},
 {t:"tf",q:"Chet elda tartib-qoidalarga rioya qilmasak ham bo‘ladi.",a:false,e:"Noto‘g‘ri. Jamoat joylarida odob saqlab, qoidalarga rioya qilish shart."},
 {t:"f",q:"Qaysi mamlakatga sayohat qilishni xohlaysiz va unga qanday tayyorlanasiz?",e:"Masalan: u haqida ma’lumot to‘playman, salomlashish va rahmat so‘zlarini hamda urf-odatlarini o‘rganaman."}]},
{id:"m4",n:"4-mavzu",t:"Sayyoramizga nimalar xavf solmoqda?",b:1,
 map:{c:"Yerni asraylik",br:[
  {t:"Plastikakl qissasi",e:"🐬",k:["Donik","plastik","okean"],x:"Dengiz jonivorlari birlashib, okeanni ko‘p yillar to‘plangan plastik chiqindidan tozalashdi."},
  {t:"Suv va havo",e:"🏭",k:["zavod chiqindisi","ozon qatlami","baliqlar"],x:"Zavod chiqindilari suv jonivorlarini qiradi, havoga chiqqanlari ozon qatlamini yemiradi."},
  {t:"Axlat va o‘rmon",e:"🌲",k:["axlatxona","yerosti suvi","kesilgan o‘rmon"],x:"Axlatdan chiqqan zaharlar ichimlik suvini ifloslaydi. O‘rmon kesilsa, jonivorlar uysiz qoladi."},
  {t:"Global isish",e:"🌡️",k:["harorat","muzliklar","qurg‘oqchilik"],x:"Harorat uzoq muddat ko‘tarilib borsa, muzliklar eriydi, dengiz sathi ko‘tariladi, ofatlar ko‘payadi."},
  {t:"Biz nima qilamiz?",e:"♻️",k:["tejash","daraxt ekish","kam plastik"],x:"Elektr va suvni tejash, chiqindini va plastmassani kamaytirish, daraxt ekish kerak."}]},
 q:[
 {t:"m",q:"«Plastikakl» hikoyasida dengiz jonivorlariga nima xavf solgan?",a:["Plastik chiqindilar","Katta qor bo‘roni","Juda toza dengiz suvi","Yangi o‘sgan suv o‘tlari"],e:"Quruqlikdan kelgan plastik chiqindilar okeanni ifloslab, jonivorlarga zarar yetkazgan."},
 {t:"m",q:"Kalmar Marikning tanasi nima yutgani uchun o‘zgarib qoldi?",a:["Neft","Qum","Tuz","Muz"],e:"Marik ko‘p neft yutib, tanasining shakli, hajmi va rangi o‘zgargan."},
 {t:"m",q:"Quyoshning zararli nurlaridan bizni nima himoya qiladi?",a:["Ozon qatlami","Dengiz to‘lqini","Tog‘ cho‘qqisi","Tutun buluti"],e:"Ozon qatlami zararli ultrabinafsha nurlardan himoya qiladi, chiqindilar esa uni yemiradi."},
 {t:"m",q:"Global isish nima?",a:["Yer haroratining uzoq vaqt ko‘tarilib borishi","Bir kun davomida havoning biroz isib qolishi","Uyda pech yoqilganda xonaning isib ketishi","Qishda har yili qorning ko‘proq yog‘ib borishi"],e:"Global isish — Yer haroratining uzoq muddat davomida uzluksiz ko‘tarilishi."},
 {t:"m",q:"Qutblardagi muzliklar erishidan qaysi jonivorlarning yashash joyi yo‘qolmoqda?",a:["Oq ayiq va pingvinlar","Tuya va kaltakesaklar","Jayron va toshbaqalar","Mushuk va kuchuklar"],e:"Oq ayiqlar, tulen va pingvinlar yashaydigan joylar yo‘qolib bormoqda."},
 {t:"m",q:"Plastmassa nega atrof-muhitga juda katta zarar yetkazadi?",a:["Ming yillar davomida chirimaydi","Yomg‘irda bir zumda erib ketadi","Tuproqqa tushsa, o‘g‘itga aylanadi","Quyoshda tezda yo‘qolib ketadi"],e:"Plastmassa ming yillar davomida chirimaydi."},
 {t:"m",q:"Global isishni kamaytirishga qaysi ish yordam beradi?",a:["Daraxt ekish","O‘rmonni kesish","Suvni bekorga oqizib qo‘yish","Avtomobilda iloji boricha ko‘p yurish"],e:"Daraxtlar toza havoni ko‘paytiradi va yovvoyi tabiatga foyda beradi."},
 {t:"tf",q:"Kiyimni keragidan ortiq sotib olmaslik tabiatga foydali.",a:true,e:"Kiyim ishlab chiqarishga juda ko‘p energiya va suv sarflanadi."},
 {t:"tf",q:"Bizning sog‘lig‘imiz Yer sayyorasining holatiga bog‘liq emas.",a:false,e:"Noto‘g‘ri. Yerga ziyon yetkazsak, o‘z sog‘lig‘imizga zarar yetkazgan bo‘lamiz."},
 {t:"f",q:"Tabiatni asrash uchun har kuni qaysi ishlarni qila olasiz?",e:"Masalan: elektr va suvni tejayman, plastikni kam ishlataman, axlat tashlamayman, daraxt ekaman."}]},
{id:"m5",n:"5-mavzu",t:"Biz qanday dunyoda yashashni istaymiz?",b:1,
 map:{c:"Kelajak dunyosi",br:[
  {t:"Kelajakni o‘ylash",e:"🔮",k:["kelajak","tengdosh","savollar"],x:"Kelajakka tushib qolsangiz, tengdoshlaringizdan nimalarni so‘rar va nimalarni aytib berardingiz?"},
  {t:"Maktub",e:"✉️",k:["kelajakka xat","yigirma yil","3-sinf"],x:"Maktub yigirma yildan keyingi uchinchi sinf o‘quvchisiga yoki o‘sha paytdagi o‘zingizga yoziladi."},
  {t:"Gazeta yoki kollaj",e:"📰",k:["kichik guruh","surat","g‘oya"],x:"Kichik guruhlarda «Biz mana shunday dunyoda yashashni istaymiz» mavzusida gazeta yoki kollaj tayyorlanadi."},
  {t:"Minnatdorchilik",e:"👏",k:["taqdimot","rahmat","hamkorlik"],x:"Ish qisqa taqdim qilinadi. Eng chiroyli surat va qiziq g‘oya bergan sinfdoshlarga rahmat aytiladi."},
  {t:"Tabiat rasmi",e:"🎨",k:["rasm","asrash","tabiat"],x:"Mavzu oxirida tabiatni asrash haqida rasm chiziladi."}]},
 q:[
 {t:"m",q:"Darslikda maktubni qayerga yozish taklif qilingan?",a:["Kelajakka","O‘tmishga","Muzeyga","Okeanga"],e:"Topshiriq: kelajakka maktub yozing."},
 {t:"m",q:"Kelajakka yozilgan maktub necha yildan keyingi o‘quvchiga yo‘llanadi?",a:["Yigirma yildan keyingi","Ikki yildan keyingi","Besh yuz yildan keyingi","Ming yildan keyingi"],e:"Maktub yigirma yildan keyin uchinchi sinfda o‘qiydigan o‘quvchiga yo‘llanadi."},
 {t:"m",q:"Maktubni yana kimga yo‘llash mumkin?",a:["O‘sha paytdagi o‘zingizga","Qadimda yashagan shohga","Ertakdagi sehrgar choliga","Dengizdagi qari baliqqa"],e:"Maktubni o‘sha paytda yashayotgan o‘zingizga ham yo‘llash mumkin."},
 {t:"m",q:"«Biz mana shunday dunyoda yashashni istaymiz» mavzusida guruhlar nima tayyorlaydi?",a:["Gazeta yoki kollaj","Palov va sumalak","Sopol idish yoki lagan","Katta yog‘och o‘tov"],e:"Kichik guruhlarda gazeta yoki kollaj tayyorlanadi."},
 {t:"m",q:"Guruh tayyorlagan ish bilan keyin nima qilinadi?",a:["Qisqa taqdimot qilinadi","Hech kimga ko‘rsatilmaydi","Darhol yirtib tashlanadi","Boshqa guruhdan yashiriladi"],e:"Tayyor ishni qisqa taqdim qilish kerak."},
 {t:"m",q:"Qiziqarli g‘oya bergan sinfdoshlarga nima qilish kerak?",a:["Minnatdorchilik bildirish","Ustidan kulib qo‘yish","G‘oyasini yashirib olish","Ular bilan gaplashmaslik"],e:"Eng chiroyli surat topgan va qiziq g‘oya bergan sinfdoshlarga rahmat aytiladi."},
 {t:"m",q:"Mavzu oxirida qaysi mavzuda rasm chizish topshirilgan?",a:["Tabiatni asrash","Sport o‘yinlari","Qadimgi qal’alar","Milliy taomlar"],e:"Topshiriq: tabiatni asrash mavzusida rasm chizing."},
 {t:"tf",q:"Gazeta yoki kollaj kichik guruhlarda tayyorlanadi.",a:true,e:"Bu ish sinfdoshlar bilan birgalikda bajariladi."},
 {t:"tf",q:"Kelajakka maktubda o‘z hayotingiz haqida yozish mumkin emas.",a:false,e:"Noto‘g‘ri. Darslik o‘z hayotingiz haqida nimalar gapirib berishingizni o‘ylab ko‘rishni so‘raydi."},
 {t:"f",q:"Siz qanday dunyoda yashashni istaysiz? Uchta orzuingizni ayting.",e:"Masalan: tabiat toza bo‘lsin, odamlar ahil yashasin, hech kim xafa qilinmasin."}]},
{id:"m6",n:"6-mavzu",t:"Tenglik nima?",b:2,
 map:{c:"Tenglik",br:[
  {t:"Biz — insonlarmiz",e:"🌍",k:["teri rangi","millat","inson"],x:"Rangimiz, yoshimiz, millatimiz har xil bo‘lishi mumkin, lekin bizni inson ekanimiz birlashtiradi."},
  {t:"Inson huquqlari",e:"📜",k:["oila","ilm","kasb tanlash"],x:"Har bir inson oilali bo‘lish, ilm olish, tibbiy yordam olish va kasb tanlash huquqiga ega."},
  {t:"Teng tug‘iladi",e:"⚖️",k:["Konstitutsiya","deklaratsiya","erkin va teng"],x:"Tenglik Konstitutsiyada ham, Inson huquqlari umumjahon deklaratsiyasida ham yozilgan."},
  {t:"Majburiyatlar",e:"🏠",k:["oila","yordam","ulg‘ayish"],x:"Oilada faqat huquq emas, majburiyat ham bor. Ulg‘aygan sari ular kengayib boradi."},
  {t:"Gender tenglik",e:"👧👦",k:["qiz va o‘g‘il","bir xil huquq","hurmat"],x:"Jinsidan qat’i nazar insonlar teng: qizlar ham, o‘g‘illar ham o‘qish, sport va kasb tanlash huquqiga ega."}]},
 q:[
 {t:"m",q:"Turli bo‘lsak ham, bizni nima birlashtirib turadi?",a:["Inson ekanimiz","Ko‘zimiz rangi","Yoshimizning bir xilligi","Bir qit’ada yashashimiz"],e:"Rang, jins, yosh, millat har xil bo‘lishi mumkin, lekin biz — insonlarmiz."},
 {t:"m",q:"Inson bo‘lganimiz uchungina ega bo‘lgan huquqlar qanday ataladi?",a:["Inson huquqlari","Uy vazifalari","Sinf qoidalari","Sport shartlari"],e:"Bu huquqlar inson huquqlari deb ataladi."},
 {t:"m",q:"Quyidagilardan qaysi biri har bir insonning huquqi?",a:["Ilm olish","Birovni xafa qilish","Boshqalar narsasini olish","Qoidalarni xohlagancha buzish"],e:"Har bir inson ilm olish, tibbiy yordam olish, kasb tanlash huquqiga ega."},
 {t:"m",q:"Deklaratsiyaga ko‘ra, hamma odamlar qanday bo‘lib tug‘iladi?",a:["Erkin va teng","Boy va kambag‘al","Kuchli va kuchsiz","Katta va kichik"],e:"Hamma odamlar qadr-qimmati va huquqlarida erkin va teng bo‘lib tug‘iladi."},
 {t:"m",q:"Nega oilada faqat huquqlar emas, majburiyatlar ham bor?",a:["Har bir a’zo boshqalarga yordam berishi kerak","Faqat eng kichik bola hamma ishni qilishi shart","Oilada hech kim hech narsa olmasligi kerak","Majburiyatlar faqat mehmonlarga berib qo‘yiladi"],e:"Inson oiladan kerakli narsalarni oladi va qo‘lidan kelganicha boshqalarga yordam beradi."},
 {t:"m",q:"Ayol va erkaklarning munosabatlardagi tengligi nima deyiladi?",a:["Gender tenglik","Global isish","Ichki intizom","Volontyorlik"],e:"Jinsidan qat’i nazar insonning munosabatlardagi tengligi gender tenglik deyiladi."},
 {t:"m",q:"O‘z huquqini himoya qilayotgan inson nimani unutmasligi kerak?",a:["Boshqalarda ham shunday huquqlar borligini","O‘zining huquqi hammanikidan ustunligini","Kichiklarning umuman huquqi yo‘qligini","Faqat kuchli odam haq bo‘lib chiqishini"],e:"Birovlarning haq-huquqlarini hurmat qiling!"},
 {t:"tf",q:"Qiz bolalar ham, o‘g‘il bolalar ham sport bilan shug‘ullanish huquqiga ega.",a:true,e:"Ular ilm olish, sport va san’at, kasb tanlashda teng huquqli."},
 {t:"tf",q:"Uy ishlarini faqat qizlar qilishi kerak.",a:false,e:"Noto‘g‘ri. Tenglik va oiladagi majburiyatlar nuqtayi nazaridan har bir a’zo yordam beradi."},
 {t:"f",q:"O‘g‘il va qiz bolalar tengligiga hayotingizdan misol keltiring.",e:"Masalan: ikkalasi ham maktabda o‘qiydi, to‘garak tanlaydi, uyda yordam beradi."}]},
{id:"m7",n:"7-mavzu",t:"Kamsitish nima?",b:2,
 map:{c:"Kamsitishga yo‘q",br:[
  {t:"Kamsitish",e:"🚫",k:["huquq buzilishi","yomon munosabat","muammo"],x:"Kamsitish — ma’lum toifadagi insonlarga ko‘r-ko‘rona yomon munosabatda bo‘lib, huquqini poymol qilish."},
  {t:"Nega paydo bo‘ladi?",e:"🤔",k:["o‘zimiznikilar","begonalar","bosim"],x:"Odamlar ba’zan «o‘zimiznikilar» va «begonalar» deb ajratadi va o‘ziga o‘xshamaganlarga bosim qiladi."},
  {t:"Sabab bo‘ladigan farqlar",e:"🧩",k:["teri rangi","til","din"],x:"Ba’zilarni terisi rangi, jinsi, yoshi, millati, dini yoki tili uchun yakkalab qo‘yishadi."},
  {t:"Belgilari",e:"👀",k:["haqorat","nafrat","ustun bilish"],x:"Haqorat qilish, past sanash, boshqa an’analarga nafrat bilan qarash — kamsitish belgilari."},
  {t:"Farqini bil",e:"💬",k:["tortishuv","kamsitish","hurmat"],x:"Bolalar o‘rtasidagi oddiy tortishuv va kamsitish boshqa-boshqa narsalar."}]},
 q:[
 {t:"m",q:"Kamsitish nimaga olib keladi?",a:["Insonlarning huquqlari buzilishiga","Hamma odamlarning ahil bo‘lishiga","Sinfda do‘stlikning yanada kuchayishiga","Insonlarning bir-birini hurmat qilishiga"],e:"Kamsitish millionlab insonlar huquqlari poymol bo‘lishiga olib keladi."},
 {t:"m",q:"Kamsitishga nima sabab bo‘ladi?",a:["«O‘zimiznikilar» va «begonalar»ga ajratish","Hammaga bir xil mehr bilan qarashga odatlanish","Yangi do‘st orttirishga juda qiziqib qolish","Boshqa xalqlarning tilini o‘rganishga urinish"],e:"Inson tabiatida «o‘zimiznikilar» va «begonalar»ga ajratishga moyillik bor."},
 {t:"m",q:"Kamsitishdan ayniqsa kimlar qattiq ozor chekadi?",a:["Imkoniyati cheklangan odamlar","Sportda g‘olib bo‘lgan odamlar","Muzeyga tez-tez boradigan odamlar","Ko‘p kitob sotib oladigan odamlar"],e:"Imkoniyati cheklangan, nogiron odamlar bunday ajratishdan juda qiynaladi."},
 {t:"m",q:"Qaysi biri kamsitish belgisi?",a:["Odamni o‘zidan past sanab, haqoratlash","G‘irrom o‘ynagan do‘st bilan bugun o‘ynamaslik","Xafa bo‘lib, bir kun o‘yinga chiqmaslik","Mehmonga borolmasligini odob bilan aytish"],e:"Odamni past sanab haqoratlash, xo‘rlash — kamsitishning belgisi."},
 {t:"m",q:"Qaysi gapda kamsitish bor?",a:["Bola imkoniyati cheklangan bolalar ustidan kuldi","Bola sinfdoshinikiga mehmonga borishdan bosh tortdi","Bola o‘rtog‘idan xafa bo‘lib, o‘yinga bormadi","Bola charchagani uchun to‘p o‘ynashni xohlamadi"],e:"Tashqi belgi yoki imkoniyati uchun odam ustidan kulish — kamsitish."},
 {t:"m",q:"Kamsitishning yana bir belgisi qaysi?",a:["O‘zgalardan o‘zini ustun bilish","O‘zgalarning fikrini tinglash","O‘zgalarga yordam qo‘lini cho‘zish","O‘zgalar madaniyatiga qiziqish"],e:"O‘zidan boshqacha odamlardan o‘zini ustun bilish — kamsitish belgisi."},
 {t:"m",q:"«Qiz bola bo‘lganing uchun to‘garakka olmaymiz» degan gapda nima ko‘rinadi?",a:["Kamsitish","Mehmondo‘stlik","Volontyorlik","Minnatdorchilik"],e:"Odamni jinsi uchun chetga surish — kamsitish, tenglik huquqi buziladi."},
 {t:"tf",q:"Bunday yomon munosabat ba’zan maktabda va sinfda ham uchraydi.",a:true,e:"Afsuski, kamsitish maktabda, sinfda ham uchrab turadi."},
 {t:"tf",q:"Har qanday tortishuv albatta kamsitish bo‘ladi.",a:false,e:"Noto‘g‘ri. Kamsitish va o‘zaro tortishuv boshqa-boshqa narsalar, farqini bilish kerak."},
 {t:"f",q:"Sinfingizda kamsitish bo‘lmasligi uchun nima qila olasiz?",e:"Masalan: hammani hurmat qilaman, masxara qilmayman, chetda qolganni o‘yinga qo‘shaman, kattalarga aytaman."}]},
{id:"m8",n:"8-mavzu",t:"Sinfdagi muhit",b:2,
 map:{c:"Ahil sinf",br:[
  {t:"O‘yinmi, masxarami?",e:"🧢",k:["qalpoq o‘yini","kulgi","xafa bo‘lish"],x:"O‘yinda hamma xursand bo‘lishi kerak. Bir bolani har kuni masxara qilish o‘yin emas."},
  {t:"Bulling",e:"⚠️",k:["xo‘rlash","yakkalash","g‘iybat"],x:"Birovni doim xafa qilish, qo‘rqitish, yakkalab qo‘yish, yomon gap tarqatish — bulling."},
  {t:"Jamoa kasalligi",e:"🩹",k:["butun sinf","birlashish","davolash"],x:"Bulling — jamoaning kasali. Uni hamma birlashib yo‘q qilishi mumkin."},
  {t:"Yangi o‘quvchi",e:"🎒",k:["Komila","o‘qituvchi","do‘stlik"],x:"Komilaning duduqlanishidan kulishdi, o‘qituvchi to‘xtatdi. Keyin bolalar u bilan do‘stlashdi."},
  {t:"Yordam berish",e:"🤗",k:["indamay turmaslik","kechirim","ustoz"],x:"Masxarani to‘xtatish, xafa bo‘lganni qo‘llash, kerak bo‘lsa ustozga aytish kerak."}]},
 q:[
 {t:"m",q:"Birovni doim xafa qilish, qo‘rqitish va turtkilash ingliz tilida nima deyiladi?",a:["Bulling","Optimist","Eksponat","Volontyor"],e:"Doimiy haqorat, zarar yetkazish, qo‘rqitish — bulling."},
 {t:"m",q:"Qaysi holat ham bulling hisoblanadi?",a:["Bir bolani yakkalab, g‘iybat qilish","Hamma qo‘shiladigan o‘yin o‘ynash","Yangi o‘quvchi bilan tanishib olish","Xato qilgan do‘stni tinch tushuntirish"],e:"Yakkalab qo‘yish, gaplashmaslik, yomon gap tarqatish ham bulling."},
 {t:"m",q:"O‘yin hamma uchun yaxshi ekanini qanday bilamiz?",a:["Hamma xohlab o‘ynaydi va xursand bo‘ladi","Bir bola yig‘laydi, qolganlari kulaveradi","Kimdir qo‘rqsa ham, o‘yin davom etaveradi","Bir kishini har kuni masxara qilishadi"],e:"Haqiqiy o‘yinda hamma o‘z xohishi bilan qatnashadi va hech kim xafa bo‘lmaydi."},
 {t:"m",q:"Komila yangi sinfga kirganda ba’zi bolalar nega kulishdi?",a:["U hayajondan duduqlanib salom berdi","U darsga qalpoq o‘ynab kirib keldi","U doskada masalani xato yechib qo‘ydi","U salom bermay, joyiga o‘tirib oldi"],e:"Komila hayajonlansa, ko‘proq duduqlanardi."},
 {t:"m",q:"Umida qo‘pol gapirganda o‘qituvchi nima dedi?",a:["Sinfimizda bunday muomala qilinmaydi","Bu juda qiziq hazil, davom etaveringlar","Komila boshqa sinfga o‘ta qolsin","Bu ishga mening hech aloqam yo‘q"],e:"O‘qituvchi Umidaning qo‘pol gapirganini aytib, uni to‘xtatdi."},
 {t:"m",q:"Bulling butun sinfning kasali bo‘lsa, uni qanday davolash kerak?",a:["Hamma birgalikda","Faqat jim turib","Bir-birini ayblab","Ko‘rmaganga olib"],e:"Uni birgalikda davolash kerak; xohish bo‘lsa, yo‘qotish oson."},
 {t:"m",q:"Sinfdoshingizni masxara qilishayotganini ko‘rsangiz, qaysi ish to‘g‘ri?",a:["«Bu yaxshi emas, to‘xtataylik» deyish","Aralashmay, chetda jimgina kuzatib turish","Kulayotganlarga qo‘shilib birga kulish","«Kuchlilar haq» deb ularni qo‘llab turish"],e:"Masxarani to‘xtatishga chaqirish, xafa bo‘lganni qo‘llash, ustozga aytish kerak."},
 {t:"tf",q:"Sinfda o‘zaro hurmat va ahillik bo‘lsa, bulling paydo bo‘lmaydi.",a:true,e:"Ahil va hurmatli sinfda bullingga o‘rin qolmaydi."},
 {t:"tf",q:"Anvar masalada xato qilsa va uni «ahmoq» deyishsa, u rostdan ahmoq bo‘lib qoladi.",a:false,e:"Yo‘q. Haqorat so‘z insonni yomon qilmaydi, aksincha, aytgan odam haqida yomon taassurot qoldiradi."},
 {t:"f",q:"Sinfingizga yangi o‘quvchi kelsa, unga qanday yordam berasiz?",e:"Masalan: tanishaman, maktabni ko‘rsataman, birga o‘tiraman va o‘ynayman, ustidan kulishlariga yo‘l qo‘ymayman."}]},
{id:"m9",n:"9-mavzu",t:"Volontyorlik",b:2,
 map:{c:"Volontyorlik",br:[
  {t:"Volontyor kim?",e:"🙌",k:["beg‘araz","maoshsiz","yordam"],x:"Volontyorlar — odamlarga beg‘araz yaxshilik qilish uchun birlashgan insonlar. Ularga maosh to‘lanmaydi."},
  {t:"Eko-volontyorlar",e:"🌱",k:["Sevara va Anna","ko‘chat","sug‘orish"],x:"Sevara va Anna har kuni kechqurun mahalladagi ko‘chatlarni sug‘oradi."},
  {t:"Savobli ish",e:"✨",k:["foyda","duo","hashar"],x:"Odamlarga foyda keltirib, evaziga faqat duo olinadigan ish savobli ish deyiladi."},
  {t:"Keksalarga yordam",e:"👵",k:["uy tozalash","do‘kon","aravacha"],x:"Bolalar keksa ayolning uyini tozalaydi, xarid qiladi, o‘g‘li aravachasini ko‘chaga chiqarishga yordam beradi."},
  {t:"Jonivorlarga mehr",e:"🐶",k:["boshpana","Dilorom opa","ovqat"],x:"Alina, Komila va Sardor daydi itlar boshpanasiga borib, somon almashtirdi va suv berdi."}]},
 q:[
 {t:"m",q:"Volontyorlar kimlar?",a:["Beg‘araz yaxshilik qiladigan insonlar","Faqat maosh uchun ishlaydigan insonlar","Faqat sport bilan shug‘ullanadigan insonlar","Muzeyda eksponat qo‘riqlaydigan insonlar"],e:"Volontyorlar odamlarga beg‘araz yaxshilik qilish uchun birlashadi."},
 {t:"m",q:"Sevara va Anna har kuni kechqurun nima qiladi?",a:["Ko‘chatlarni sug‘oradi","Daraxtlarni kesadi","Do‘konda narsa sotadi","Avtobus haydab yuradi"],e:"Qizlar uydan chelakda suv olib chiqib, ko‘chatlarni sug‘oradi."},
 {t:"m",q:"Chinor va emanning soya beradigan daraxt bo‘lishiga kamida qancha vaqt kerak?",a:["Qirq-ellik yil","Bir-ikki oy","To‘rt-besh kun","Ikki-uch hafta"],e:"Sevaraning buvisi aytganidek, kamida qirq-ellik yil kerak."},
 {t:"m",q:"Kuchli shamoldan keyin ko‘chatlar sinmasligi uchun nima qilindi?",a:["Yog‘och ustunlarga bog‘landi","Hammasi uyga olib kirildi","Ustiga qalin gilam yopildi","Barcha shoxlari kesib tashlandi"],e:"Ko‘chatlar yoniga ustun qoqib bog‘landi, butun mahalla hashar qildi."},
 {t:"m",q:"Savobli ish qanday ish?",a:["Foyda keltirib, evaziga duo olinadigan ish","Faqat katta pul va sovg‘a evaziga qilinadigan ish","O‘ziga foyda, boshqalarga zarar yetkazadigan ish","Hech kimga hech qanday foydasi tegmaydigan ish"],e:"Odamlarga foyda keltiradigan va evaziga faqat duo olinadigan ishlar savobli ish."},
 {t:"m",q:"Alina, Komila va Sardor volontyor bo‘lish uchun qayerga murojaat qildi?",a:["Daydi itlar boshpanasiga","Shahar san’at muzeyiga","Sport to‘garagi rahbariga","Mahalladagi non do‘koniga"],e:"Ular daydi itlar uchun tashkil etilgan boshpana rahbariga qo‘ng‘iroq qilishdi."},
 {t:"m",q:"Dilorom opa bolalardan qaysi ishni iltimos qildi?",a:["Somonni almashtirib, itlarga suv berishni","Itlarni ko‘chaga qo‘yib yuborib, ortidan quvishni","Boshpana devorlarini yangidan qurib chiqishni","Bozordan yangi kuchukchalar sotib kelishni"],e:"Bolalar itlar tagidagi somonni almashtirib, keyin suv berishdi."},
 {t:"tf",q:"Volontyorlarga oylik maosh to‘lanmaydi.",a:true,e:"Volontyorlik — xolis, beg‘araz xizmat."},
 {t:"tf",q:"Rasm chizib, yaxshi g‘oyalarni tarqatish volontyorlik bo‘la olmaydi.",a:false,e:"Noto‘g‘ri. Rasm chizish, suratga olish, yaxshi g‘oya tarqatish ham volontyorlik."},
 {t:"f",q:"Siz qaysi savobli ishni tanlar edingiz va nega?",e:"Masalan: keksalarga yordam berish, ko‘chat sug‘orish, hasharda qatnashish, jonivorlarga qarash."}]},
{id:"m10",n:"10-mavzu",t:"Men hayotni sevaman!",b:3,
 map:{c:"Hayotni sevish",br:[
  {t:"Ertak qahramonlari",e:"🐻",k:["Vinni Pux","Xo‘tikvoy","dum"],x:"Xomush Xo‘tikvoy dumini yo‘qotdi. Vinni Pux uni topib berishga ahd qildi."},
  {t:"Optimist",e:"😊",k:["yaxshi tomon","quvonch","umid"],x:"Optimist har qanday voqeaning yaxshi tomonini ko‘radi, hayotga quvonch bilan qaraydi."},
  {t:"Pessimist",e:"😟",k:["tushkunlik","yomon tomon","shikoyat"],x:"Pessimist tushkunlikka moyil, har vaziyatning faqat yomon tomonini ko‘radi."},
  {t:"Shukr",e:"🌞",k:["ne’mat","xursandlik","shukr"],x:"Hayotni sevish — har bir ne’matga xursand bo‘lib, shukr qilish."},
  {t:"Xushchaqchaqlik",e:"🎈",k:["kayfiyat","ko‘ngil","do‘stlar"],x:"Xushchaqchaq odam atrofdagilarni ham xursand qilib, ko‘nglini ko‘taradi."}]},
 q:[
 {t:"m",q:"Ertakda Xo‘tikvoy nimasini yo‘qotib qo‘ygan?",a:["Dumini","Do‘ppisini","Kitobini","Chelagini"],e:"Vinni Pux Xo‘tikvoyning dumi yo‘qligini payqadi."},
 {t:"m",q:"Vinni Pux Xo‘tikvoyga qanday yordam berishga ahd qildi?",a:["Dumini topib berishga","Yangi uy qurib berishga","Unga masala yechib berishga","Uni boshqa o‘rmonga ko‘chirishga"],e:"Vinni Pux: dumingni topib beraman, dedi."},
 {t:"m",q:"Optimist qanday odam?",a:["Har voqeaning yaxshi tomonini ko‘radi","Har narsaning faqat yomon tomonini ko‘radi","Hamma narsadan doim shikoyat qilib yuradi","Har qanday ishda darrov tushkunlikka tushadi"],e:"Optimist hayotga quvonch bilan qaraydi."},
 {t:"m",q:"Tushkunlikka moyil, faqat yomon tomonni ko‘radigan odam kim?",a:["Pessimist","Optimist","Volontyor","Eksponat"],e:"Pessimist har qanday vaziyatning faqat yomon tomonini ko‘radi."},
 {t:"m",q:"Qaysi gapni optimist odam aytadi?",a:["Qishda qor yog‘adi, qorbo‘ron o‘ynaymiz!","Baribir yutqazaman, shuning uchun o‘ynamayman","Ekskursiyaga bormayman, u yerda zerikaman","Vazifa juda qiyin, baribir xato qilaman"],e:"Optimist hatto sovuq qishda ham quvonarli narsani topadi."},
 {t:"m",q:"Hayotni sevish nima degani?",a:["Har bir ne’matga xursand bo‘lib, shukr qilish","Har kuni biror narsadan norozi bo‘lib yurish","Faqat o‘zini o‘ylab, boshqalarni unutib qo‘yish","Qiyin ish chiqsa, darrov undan voz kechish"],e:"Hayotni sevish — ne’matlarga xursand bo‘lib, shukr qilish."},
 {t:"m",q:"Xushchaqchaq odam atrofdagilarga qanday ta’sir qiladi?",a:["Ko‘nglini ko‘taradi","Jahlini chiqaradi","Ularni zeriktirib qo‘yadi","Ularni doim xafa qiladi"],e:"Xushchaqchaq odam boshqalarni ham xursand qiladi."},
 {t:"tf",q:"Xo‘tikvoy Vinni Puxni haqiqiy do‘st deb aytdi.",a:true,e:"Xo‘tikvoy: rahmat, sen haqiqiy do‘stsan, dedi."},
 {t:"tf",q:"Pessimist har bir ishdan faqat yaxshilik kutadi.",a:false,e:"Noto‘g‘ri. Pessimist faqat yomon tomonni ko‘radi; yaxshilikni ko‘ruvchi — optimist."},
 {t:"f",q:"«Uy vazifasi qiyin, baribir xato qilaman» degan gapni optimistcha qanday aytasiz?",e:"Masalan: vazifa qiyin, lekin harakat qilsam o‘rganaman, xatolarim menga saboq bo‘ladi."}]},
{id:"m11",n:"11-mavzu",t:"His-tuyg‘ularimiz",b:3,
 map:{c:"His-tuyg‘ular",br:[
  {t:"Hissiyot",e:"💓",k:["shodlik","qayg‘u","qo‘rquv"],x:"Hissiyot — his-tuyg‘ularimizning ifodasi: shodlik, qayg‘u, g‘azab, taajjub, qo‘rquv."},
  {t:"Kayfiyat",e:"🌈",k:["sog‘liq","umr","ta’sir"],x:"Yaxshi kayfiyat sog‘liqqa foydali, yomoni zarar qilishi va boshqalar kayfiyatini buzishi mumkin."},
  {t:"Tushunish",e:"👂",k:["o‘zini","boshqalarni","muomala"],x:"O‘zi va boshqalar hislarini tushunadigan odam muomalada qiynalmaydi."},
  {t:"Nomini aytish",e:"🗣️",k:["xafa bo‘ldim","jahlim chiqdi","qo‘llab-quvvatlash"],x:"Salbiy hisning nomini aytsak, u kamayadi, do‘stlar esa iliq so‘z bilan qo‘llaydi."},
  {t:"Yengish yo‘llari",e:"🔑",k:["sababni topish","harakat","yo‘l izlash"],x:"Salbiy hisning sababini aniqlash va harakat qilib kayfiyatni ko‘tarish yordam beradi."}]},
 q:[
 {t:"m",q:"Hissiyot nima?",a:["His-tuyg‘ularimizning ifodasi","Har kuni takrorlanadigan ish","Ovqatlarning besh xil guruhi","Muzeyga qo‘yilgan qadimiy buyum"],e:"Hissiyot — bu his-tuyg‘ularimizning ifodasi."},
 {t:"m",q:"Quyidagilardan qaysi biri hissiyot?",a:["Shodlik","Daftar","Nonushta","Qo‘ng‘iroq"],e:"Shodlik, qayg‘u, g‘azab, taajjub, qo‘rquv — hissiyotlar."},
 {t:"m",q:"Yaxshi kayfiyat insonga qanday ta’sir qiladi?",a:["Sog‘liqqa foydali, umrni uzaytiradi","Sog‘liqqa zarar qilib, kuchni kamaytiradi","Atrofdagilarning kayfiyatini albatta buzadi","Insonni boshqalar bilan urishtirib qo‘yadi"],e:"Yaxshi kayfiyat sog‘liq uchun foydali, umrni uzaytiradi."},
 {t:"m",q:"Salbiy hisni jilovlash usullaridan biri qaysi?",a:["Uning nomini aytish","Uni hammadan yashirish","Do‘stlarga baqirib berish","Narsalarni sindirib tashlash"],e:"«Jahlim chiqdi», «Qo‘rqib ketdim» kabi nomini aytsak, salbiy his kamayadi."},
 {t:"m",q:"Hisingiz nomini aytsangiz, o‘rtoqlaringiz nima qilishi mumkin?",a:["Iliq so‘z bilan qo‘llab-quvvatlashi","Ustingizdan kulib, masxara qilishi","Siz bilan gaplashmay qo‘yishi","Jahlingizni yanada chiqarishi"],e:"O‘rtoqlar sizni qo‘llab-quvvatlash uchun iliq so‘zlar topadi."},
 {t:"m",q:"Salbiy hisning sababini aniqlasangiz, nima qila olasiz?",a:["Keyingi safar uning oldini olasiz","Butunlay hech narsani his qilmaysiz","Hamma aybni do‘stingizga to‘nkaysiz","Har kuni o‘sha holatni takrorlaysiz"],e:"Sababini aniqlay olsangiz, keyingi safar oldini olish mumkin."},
 {t:"m",q:"O‘zining va boshqalarning hislarini tushunadigan odam nimada qiynalmaydi?",a:["Boshqalar bilan muomala qilishda","Og‘ir yuklarni ko‘tarib yurishda","Baland tog‘larga chiqib borishda","Chet tilidagi kitobni o‘qishda"],e:"Bunday odam boshqalar bilan muomalada aslo qiynalmaydi."},
 {t:"tf",q:"Yomon kayfiyat boshqalarning ham kayfiyatini buzishi mumkin.",a:true,e:"Kayfiyatimiz o‘zimizga ham, atrofdagilarga ham ta’sir qiladi."},
 {t:"tf",q:"Yomon vaziyatdan chiqishning hech qachon yo‘li bo‘lmaydi.",a:false,e:"Noto‘g‘ri. Har qanday vaziyatdan chiqishning, albatta, bir yo‘li bor."},
 {t:"f",q:"Kayfiyatingiz buzilsa, uni ko‘tarish uchun nima qilasiz?",e:"Masalan: hisim nomini aytaman, sababini topaman, yaqinlarim bilan gaplashaman, yoqqan ish bilan shug‘ullanaman."}]},
{id:"m12",n:"12-mavzu",t:"Mening odatlarim",b:3,
 map:{c:"Odatlar",br:[
  {t:"Odat nima?",e:"🔁",k:["har kuni","takrorlash","xatti-harakat"],x:"Odat — inson uchun odatiy bo‘lib qolgan, doim qilib yuradigan ishlar."},
  {t:"Yaxshi odatlar",e:"💪",k:["badantarbiya","yuvinish","tartib"],x:"Yaxshi odatlar bizni kuchli, sog‘lom, aqlli qiladi va rivojlantiradi."},
  {t:"Yomon odatlar",e:"📱",k:["aldash","tirnoq tishlash","ko‘p telefon"],x:"Yomon odatlar zarar keltiradi, xalaqit beradi, lekin ko‘pincha buni sezmaymiz."},
  {t:"Uyqu rejimi",e:"⏰",k:["Alisher","kech uxlash","ulgurmaslik"],x:"Alisher kech uxlagani uchun nonushtaga ulgurmadi va darsni tushunishga qiynaldi."},
  {t:"21 kun va eko-odat",e:"🌿",k:["21 kun","iroda","shamollatish"],x:"Ish kamida 21 kun takrorlansa, odatga aylanar ekan. Xonani shamollatish, gul sug‘orish — eko-odatlar."}]},
 q:[
 {t:"m",q:"Odat nima?",a:["Doim qilib yuradigan ishlarimiz","Faqat bir marta qilingan ish","Boshqa odamning bizga bergan sovg‘asi","Muzeyga qo‘yilgan buyumlar to‘plami"],e:"Odat — inson uchun odatiy bo‘lib qolgan xatti-harakatlar."},
 {t:"m",q:"Qaysi biri foydali odat?",a:["Tishlarni tozalash","Tirnoqni tishlash","Yotgan holda kitob o‘qish","Fastfudni juda ko‘p yeyish"],e:"Tishlarni tozalash sog‘liq uchun foydali."},
 {t:"m",q:"Qaysi biri zararli odat?",a:["Bukchayib o‘tirish","Ertalab yuvinish","Narsalarni joyiga qo‘yish","Vazifani vaqtida bajarish"],e:"Bukchayib yurish va o‘tirish zararli odat."},
 {t:"m",q:"Alisherning kuni nega yomon boshlandi?",a:["Yarim tungacha uxlamagani uchun","Juda erta uxlab qolgani uchun","Ertalab badantarbiya qilgani uchun","Kechqurun sumkasini yig‘gani uchun"],e:"Kech uxlagani sababli turishga qiynaldi, nonushtaga ham ulgurmadi."},
 {t:"m",q:"Yaxshi odatga o‘rganish uchun nima qilish kerak?",a:["Uni doim, bir vaqtda erinmay takrorlash","Uni oyda bir marta eslab, qilib qo‘yish","Faqat kimdir majbur qilgandagina bajarish","Qiyin tuyulsa, birinchi kuniyoq tashlash"],e:"Ishni doim, bir vaqtda, erinmay takrorlash kerak."},
 {t:"m",q:"Ish odatga aylanishi uchun kamida necha kun takrorlanishi kerak?",a:["21 kun","2 kun","5 kun","7 kun"],e:"Bir ish kamida 21 kun takrorlansa, odatga aylanar ekan."},
 {t:"m",q:"Qaysi biri eko-odat?",a:["Chiqindini turlarga ajratish","Telefonni kechgacha o‘ynash","Quloqchinni doim taqib yurish","Darsga tayyorlanmay borish"],e:"Chiqindini ajratish, xonani shamollatish, gullarni sug‘orish — eko-odatlar."},
 {t:"tf",q:"Kompyuterda ishlaganda ko‘zni vaqti-vaqti bilan dam oldirish foydali odat.",a:true,e:"Bu ko‘z sog‘lig‘ini asraydi."},
 {t:"tf",q:"Yomon odatlarning zararini biz har doim darrov sezamiz.",a:false,e:"Noto‘g‘ri. Ko‘pincha biz buni sezmaymiz yoki tushunmaymiz."},
 {t:"f",q:"Qaysi yangi yaxshi odatni o‘rganmoqchisiz va uni qanday boshlaysiz?",e:"Masalan: ertalab badantarbiya — 21 kun bir vaqtda qilib, kundalikda belgilab boraman."}]},
{id:"m13",n:"13-mavzu",t:"Mening sog‘lig‘im",b:3,
 map:{c:"Sog‘lom ovqatlanish",br:[
  {t:"Donli mahsulotlar",e:"🍞",k:["non","guruch","kletchatka"],x:"Non, guruch, makaron, yorma, kartoshka ovqatimizning uchdan biri bo‘lishi kerak. Ular quvvat beradi."},
  {t:"Sut mahsulotlari",e:"🥛",k:["kalsiy","vitaminlar","bolalar"],x:"Sut mahsulotlari kalsiy va vitaminlarga boy, bolalar tanasi rivojlanishiga yordam beradi."},
  {t:"Oqsilli ovqatlar",e:"🍗",k:["go‘sht","baliq","loviya"],x:"Go‘sht, baliq, loviya, no‘xat, yong‘oqda oqsil ko‘p, ular immunitetni mustahkamlaydi."},
  {t:"Meva va sabzavot",e:"🍎",k:["vitamin","yarmi","quritish"],x:"Meva va sabzavotlar oziqamizning yarmi bo‘lishi kerak."},
  {t:"Me’yor",e:"🍬",k:["yog‘","shirinlik","Sevara"],x:"Yog‘li ovqat, shirinlik va gazli ichimlikni kam iste’mol qilish kerak. Sevara buni kasal bo‘lib tushundi."}]},
 q:[
 {t:"m",q:"Darslikda oziq-ovqatlar nechta guruhga bo‘lingan?",a:["Besh guruhga","Ikki guruhga","O‘nta guruhga","Yigirma guruhga"],e:"Oziq-ovqat mahsulotlari besh guruhga bo‘linadi."},
 {t:"m",q:"Qaysi mahsulot donli mahsulotlar guruhiga kiradi?",a:["Guruch","Baliq","Muzqaymoq","Kungaboqar yog‘i"],e:"Non, guruch, makaron, yorma va kartoshka shu guruhga kiradi."},
 {t:"m",q:"Sut mahsulotlari nimaga boy?",a:["Kalsiy va vitaminlarga","Gaz va bo‘yoqlarga","Shakar va shokoladga","Zararli kimyoviy moddalarga"],e:"Sut mahsulotlari kalsiy va boshqa vitaminlarga boy."},
 {t:"m",q:"Qaysi mahsulotlar go‘shtning o‘rnini bosishi mumkin?",a:["Dukkaklilar","Shirinliklar","Gazli ichimliklar","Shirin pishiriqlar"],e:"Loviya, no‘xat kabi dukkaklilarda oqsil va kletchatka ko‘p."},
 {t:"m",q:"Meva-sabzavotlar kunlik ovqatimizning qancha qismi bo‘lishi kerak?",a:["Yarmi","O‘ndan biri","Juda ozgina qismi","Umuman bo‘lmasa ham bo‘ladi"],e:"Vitaminlarga boy meva-sabzavotlar oziqalarning yarmini tashkil qilishi kerak."},
 {t:"m",q:"Qaysi mahsulotlarni iloji boricha kamroq yeyish kerak?",a:["Shokolad va gazli ichimliklar","Olma va boshqa yangi mevalar","Sabzi va boshqa sabzavotlar","Loviya va no‘xatli taomlar"],e:"Shokolad, shirin pishiriq, gazli ichimliklarni kam iste’mol qilish kerak."},
 {t:"m",q:"Sevara nega kasalxonaga tushib qoldi?",a:["Noto‘g‘ri ovqatlangani uchun","Sovuqda ko‘p yurgani uchun","Sport bilan shug‘ullangani uchun","Ertalab barvaqt turgani uchun"],e:"U juda ko‘p shirinlik yerdi; shifokor sabab noto‘g‘ri ovqatlanish ekanini aytdi."},
 {t:"tf",q:"To‘g‘ri ovqatlansak, suyak va tishlar mustahkam bo‘ladi.",a:true,e:"Shuningdek, immunitet va xotira yaxshilanadi."},
 {t:"tf",q:"Yog‘ inson tanasiga umuman kerak emas.",a:false,e:"Noto‘g‘ri. Yog‘ tana oziqlanishi uchun kerak, lekin ko‘pi zararli."},
 {t:"f",q:"Bir kunlik foydali ovqatlar ro‘yxatini tuzing.",e:"Masalan: nonushtaga yorma va sut, tushlikka sho‘rva, non va sabzavot, kechki payt meva va qatiq."}]},
{id:"m14",n:"14-mavzu",t:"O‘zimni boshqaraman",b:3,
 map:{c:"Ichki intizom",br:[
  {t:"Ertalabki tartib",e:"🌅",k:["soat 6","badantarbiya","21 kun"],x:"Madina do‘stiga qo‘ng‘iroqni soat 6 ga qo‘yib, darrov turishni va mashq qilishni maslahat berdi."},
  {t:"Ichki intizom",e:"🧭",k:["iroda","majburlash","maqsad"],x:"Istagan narsaga erishish uchun istamagan ishni ham qilishga o‘zini majbur qilish — ichki intizom."},
  {t:"Yordam va xalaqit",e:"📋",k:["kun tartibi","reja","dangasalik"],x:"Kun tartibi, sport, reja yordam beradi; dangasalik, bahona, tartibsizlik xalaqit qiladi."},
  {t:"Karim va Zafar",e:"🏀",k:["basketbol","mashg‘ulot","bahona"],x:"Karim mashg‘ulot qoldirmadi, Zafar esa bahona qilib yurdi."},
  {t:"Ustoz sabog‘i",e:"🌳",k:["ko‘chat","sabr","mas’uliyat"],x:"Shogird ko‘chatni parvarish qilib, sabr va mas’uliyatni o‘rgandi."}]},
 q:[
 {t:"m",q:"Istagan narsaga erishish uchun istamagan ishni qilishga o‘zini majbur qilish nima?",a:["Ichki intizom","Gender tenglik","Global isish","Eko-odat"],e:"Bu — ichki intizom."},
 {t:"m",q:"Konfutsiy yomon odatni qachon tashlash osonroq deb aytgan?",a:["Bugun","Ertaga","Keyingi yili","Katta bo‘lganda"],e:"«Yomon odatlarni ertaga emas, bugun tashlash osonroq bo‘ladi»."},
 {t:"m",q:"Ichki intizomni kuchaytirishga nima yordam beradi?",a:["Kun tartibiga rioya qilish","Har ishga bahona topish","Yarim tungacha televizor ko‘rish","Narsalarni tartibsiz tashlab qo‘yish"],e:"Kun tartibi, sport, reja tuzish va vaqtni qadrlash yordam beradi."},
 {t:"m",q:"Karim va Zafardan qaysi biri sportda g‘olib bo‘lishi mumkin va nega?",a:["Karim, chunki mashg‘ulot qoldirmaydi","Zafar, chunki filmlarni ko‘p ko‘radi","Zafar, chunki bahonani tez topadi","Karim, chunki mashqqa kam boradi"],e:"Muntazam mashq qilmagan odam chempion bo‘lolmaydi."},
 {t:"m",q:"Ustoz yosh shogirdga ilm o‘rgatishdan oldin nima buyurdi?",a:["Ko‘chat ekib, daraxt o‘stirishni","Katta qozonda palov damlashni","Tog‘ cho‘qqisiga bayroq o‘rnatishni","Muzeydagi suratlarni sanab chiqishni"],e:"Ustoz vodiyda ko‘chat ekib, undan katta daraxt o‘stirishni aytdi."},
 {t:"m",q:"Shogird nega vodiyda kulba qurib yashay boshladi?",a:["Vaqt va kuchi yo‘lga ketmasligi uchun","Ustozidan qattiq xafa bo‘lib qochgani uchun","U yerda hech narsa qilmay dam olish uchun","Uyiga ko‘p mehmon kelib turgani uchun"],e:"U ko‘chatga yaxshiroq qarash va yo‘lga ortiqcha kuch sarflamaslik uchun shunday qildi."},
 {t:"m",q:"Ustozning aytishicha, daraxtning tanasi shogirdning qaysi fazilatiga o‘xshaydi?",a:["Sabriga","Jahliga","Dangasaligiga","O‘yinqaroqligiga"],e:"Ildiz — mas’uliyat, tana — sabr, shoxlar — xotirjamlik, barglar — ilm."},
 {t:"tf",q:"Faqat xohishning o‘zi bilan ish bitmaydi, harakat va iroda ham kerak.",a:true,e:"Dangasa va o‘yinqaroq odam xohlagan narsasiga erisha olmaydi."},
 {t:"tf",q:"Hikoya boshida shogird juda sabrli va intizomli edi.",a:false,e:"Yo‘q. Ustozi aytishicha, u mas’uliyatsiz, sabrsiz va intizomsiz edi."},
 {t:"f",q:"Vaqtni behuda ketkazmaslik uchun kun tartibingizga nimalarni yozasiz?",e:"Masalan: erta turish, badantarbiya, maktab, dars tayyorlash, sport, o‘z vaqtida uxlash."}]},
{id:"m15",n:"15-mavzu",t:"An’analar — xalq xotirasidir",b:4,
 map:{c:"An’analar",br:[
  {t:"An’ana",e:"📜",k:["arabcha so‘z","avloddan avlodga","qadriyat"],x:"An’ana — kattalardan kichiklarga, avloddan avlodga o‘tadigan qadriyatlar."},
  {t:"Kulolchilik",e:"🏺",k:["loy","xumdon","lagan"],x:"Kulollar loy buyumlarni xumdonda pishirib, naqsh chizadi. Rishton — asosiy kulolchilik markazi."},
  {t:"Hunarmandchilik",e:"🧵",k:["gilam","do‘ppi","zardo‘zlik"],x:"Samarqand gilami, Chimboy o‘tovi, Chust do‘ppisi, Andijon qo‘g‘irchoqlari, Buxoro zardo‘zligi mashhur."},
  {t:"Palov",e:"🍚",k:["guruch","UNESKO","devzira"],x:"O‘zbek palovi UNESKOning madaniy meroslar ro‘yxatiga kiritilgan."},
  {t:"Oshpazlar sulolasi",e:"👨‍🍳",k:["Aziz","Karim Mahmudov","58 xil"],x:"Aziz oshpazlar oilasidan. Karim Mahmudov kitobida 58 xil palov haqida yozilgan."}]},
 q:[
 {t:"m",q:"«An’ana» so‘zi qaysi ma’noni bildiradi?",a:["Nasldan naslga o‘tadigan qoidalar","Faqat bir kun davom etadigan o‘yin","Chet eldan sotib olingan yangi buyum","Hech kimga aytilmaydigan yashirin sir"],e:"Arabcha bu so‘z «nasldan naslga o‘tadigan qoidalar» degani."},
 {t:"m",q:"Kulollar buyumlarni nimadan yasaydi?",a:["Loydan","Kigizdan","Ipakdan","Yog‘ochdan"],e:"Kulollar loy buyumlarni xumdonda pishirib, naqsh chizadi."},
 {t:"m",q:"O‘zbekistonning asosiy kulolchilik markazi qaysi shahar?",a:["Rishton","Chimboy","Chust","Qarshi"],e:"Rishton sopol va chinni buyumlari bilan dunyoga mashhur."},
 {t:"m",q:"Chimboy hunarmandlari nima tikadi?",a:["O‘tov","Zarchopon","Do‘ppi","Qo‘g‘irchoq"],e:"O‘tov — kigiz bilan yopiladigan qadimiy ko‘chma uy."},
 {t:"m",q:"Laganning orqasidagi teshikcha nima uchun kerak?",a:["Laganni devorga ilib qo‘yish uchun","Ovqatning yog‘ini oqizib olish uchun","Laganga ip bog‘lab, sudrab yurish uchun","Loyni xumdonda tezroq eritish uchun"],e:"Qadimda lagan idishgina emas, uy bezagi ham bo‘lgan."},
 {t:"m",q:"Azizning aytishicha, oshning to‘rtta asosiy masallig‘i qaysi?",a:["Guruch, yog‘, piyoz, go‘sht","Guruch, shakar, sut, olma","Un, tuxum, qaymoq, mayiz","Loviya, baliq, tuz, limon"],e:"Qolgan masalliqlar oshning turiga va ta’bga qarab qo‘shiladi."},
 {t:"m",q:"«O‘zbek palovi» kitobini kim yozgan?",a:["Karim Mahmudov","Bahodir Yo‘ldoshev","Sergey Denisenko","O‘rinboy Eskirkepov"],e:"Usta oshpaz Karim Mahmudov 30 yil davomida taomlar haqida ma’lumot to‘plagan."},
 {t:"tf",q:"O‘zbek palovi UNESKOning madaniy meroslar ro‘yxatiga kiritilgan.",a:true,e:"Palovimizni butun dunyo tan olgan."},
 {t:"tf",q:"Buxoro faqat o‘tov tikish bilan mashhur.",a:false,e:"Noto‘g‘ri. Buxoro qadimdan zargarlik va zardo‘zlik markazi."},
 {t:"f",q:"Oilangizda qanday an’ana bor? U haqda aytib bering.",e:"Masalan: bayramda palov yoki sumalak pishirish, kattalardan hunar o‘rganish, mehmon kutish."}]},
{id:"m16",n:"16-mavzu",t:"O‘zbekiston xalqlari madaniyati",b:4,
 map:{c:"Do‘stlik va madaniyat",br:[
  {t:"Do‘stlik kuni",e:"🤝",k:["30-iyul","milliy libos","bayram"],x:"30-iyulda O‘zbekiston xalqlari do‘stligi kuni nishonlanadi."},
  {t:"Ko‘p millatli yurt",e:"🌍",k:["130 dan ortiq","ahillik","madaniy markaz"],x:"Yurtimizda 130 dan ortiq millat va elat vakillari bir oiladek tinch-totuv yashaydi."},
  {t:"Milliy taomlar",e:"🥟",k:["somsa","chak-chak","beshbarmoq"],x:"O‘zbekcha somsa, tatarcha chak-chak, qozoqcha beshbarmoq, koreyscha kuksi — turli xalqlar taomlari."},
  {t:"Navro‘z",e:"🌷",k:["21-mart","sumalak","bahor"],x:"Navro‘z — bahor bayrami. 2009-yilda UNESKOning nomoddiy madaniy meros ro‘yxatiga kiritilgan."},
  {t:"Boshqa bayramlar",e:"🎉",k:["Sabantuy","Sollal","Ko‘k choshur"],x:"Sabantuy — tatarlar, Sollal — koreyslar, Ko‘k choshur — uyg‘urlar bayrami."}]},
 q:[
 {t:"m",q:"O‘zbekiston xalqlari do‘stligi kuni qachon nishonlanadi?",a:["30-iyulda","21-martda","1-sentyabrda","8-dekabrda"],e:"30-iyul — O‘zbekiston xalqlari do‘stligi kuni."},
 {t:"m",q:"Yurtimizda qancha millat va elat vakillari yashaydi?",a:["130 dan ortiq","10 taga yaqin","Faqat 3 ta","20 tadan kam"],e:"O‘zbekistonda 130 dan ortiq millat va elat vakillari istiqomat qiladi."},
 {t:"m",q:"Navro‘z bayramining asosiy taomi qaysi?",a:["Sumalak","Varenik","Kuksi","Chak-chak"],e:"Navro‘zning asosiy taomi — sumalak."},
 {t:"m",q:"Navro‘zda odamlar qanday ish qiladi?",a:["Bemor va yolg‘izlarni yo‘qlaydi","Qo‘shnilar bilan arazlashib oladi","Hech kimni tabriklamay yuradi","Uyda eshikni yopib, yolg‘iz o‘tiradi"],e:"Hamma bir-birini tabriklaydi, bemorlarni yo‘qlaydi, arazlashganlar yarashadi."},
 {t:"m",q:"Sabantuy qaysi xalqning bayrami?",a:["Tatar","Koreys","Uyg‘ur","Arman"],e:"Sabantuy — tatar xalqining bahor bayrami."},
 {t:"m",q:"Sollal nima?",a:["Koreyslarning yangi yili","Uyg‘urlarning hosil bayrami","Tatarlarning kurash musobaqasi","Qozoqlarning milliy taomi"],e:"Sollal — Koreya xalqining yangi yili."},
 {t:"m",q:"Ko‘k choshur bayramida uyg‘urlar nima pishiradi?",a:["Ko‘katli chuchvara","Asalli chak-chak","Koreyscha sho‘rva","Ukraincha varenik"],e:"Bu bayramda ko‘kat solingan chuchvara pishiriladi."},
 {t:"tf",q:"Yurtimizda turli millatlarning milliy madaniy markazlari bor.",a:true,e:"Ular madaniyat va urf-odatlarni saqlashga katta hissa qo‘shadi."},
 {t:"tf",q:"Navro‘z faqat O‘zbekistonda nishonlanadi.",a:false,e:"Noto‘g‘ri. U Qozog‘iston, Tojikiston, Eron, Turkiya va boshqa davlatlarda ham nishonlanadi."},
 {t:"f",q:"Qaysi milliy bayram sizga yoqadi? U qanday nishonlanadi?",e:"Masalan: Navro‘z — sumalak pishiriladi, milliy o‘yinlar o‘ynaladi, yaqinlar dasturxon atrofida to‘planadi."}]},
{id:"m17",n:"17-mavzu",t:"O‘zbekiston shaharlari",b:4,
 map:{c:"Shaharlarimiz",br:[
  {t:"Poytaxt",e:"🏙️",k:["Toshkent","metro","2200 yil"],x:"Toshkent — poytaxt, 2200 yillik tarixga ega, Markaziy Osiyodagi eng katta shahar."},
  {t:"Qadimiy shaharlar",e:"🕌",k:["Samarqand","Buxoro","Xiva"],x:"Samarqandda Registon, Buxoroda Minorayi Kalon, Xivada Ichan qal’a mashhur."},
  {t:"Temur va Bobur yurti",e:"👑",k:["Shahrisabz","Oqsaroy","Andijon"],x:"Shahrisabz — Amir Temur tug‘ilgan shahar. Andijon — Bobur yurti."},
  {t:"Hunar va gullar",e:"🌸",k:["Marg‘ilon","Namangan","ipak"],x:"Marg‘ilon — ipakchilik poytaxti. Namangan — gullar shahri."},
  {t:"Boshqa shaharlar",e:"🗺️",k:["Nukus","Termiz","Mo‘ynoq"],x:"Nukusda Savitskiy muzeyi, Termizda arxeologiya muzeyi bor. Mo‘ynoq Orol dengizi bilan bog‘liq."}]},
 q:[
 {t:"m",q:"O‘zbekiston poytaxti qaysi shahar?",a:["Toshkent","Samarqand","Namangan","Termiz"],e:"Toshkent — O‘zbekiston poytaxti."},
 {t:"m",q:"Amir Temur qaysi shaharda tug‘ilgan?",a:["Shahrisabzda","Andijonda","Marg‘ilonda","Nukusda"],e:"Shahrisabz — Amir Temur tug‘ilgan qadimiy shahar, u yerda Oqsaroy saqlangan."},
 {t:"m",q:"Registon qaysi shaharda joylashgan?",a:["Samarqandda","Qarshida","Mo‘ynoqda","Namanganda"],e:"Registon, Go‘ri Amir va Bibixonim — Samarqandning diqqatga sazovor obidalari."},
 {t:"m",q:"Qaysi shahar ochiq osmon ostidagi muzey shahar deyiladi?",a:["Xiva","Termiz","Nukus","Marg‘ilon"],e:"Xivaning eng mashhur joyi — Ichan qal’a."},
 {t:"m",q:"Marg‘ilon nima bilan mashhur?",a:["Ipakchilik bilan","Kemasozlik bilan","Tuz qazib olish bilan","Gullar festivali bilan"],e:"Marg‘ilon — o‘zbek ipakchiligi poytaxti: adras, atlas, beqasam, baxmal."},
 {t:"m",q:"Mamlakatimizning eng janubidagi shahar qaysi?",a:["Termiz","Nukus","Toshkent","Andijon"],e:"Termiz Amudaryo sohilida, Afg‘oniston chegarasida joylashgan."},
 {t:"m",q:"Mo‘ynoq qanday voqeadan keyin mashhur bo‘lib ketdi?",a:["Orol dengizi quriy boshlagach","Yangi metro qurib bitkazilgach","Shaharda gullar festivali o‘tkazilgach","Baland teleminora o‘rnatilgach"],e:"Dengiz tubi ochilib, ulkan tuz sahrosiga aylandi."},
 {t:"tf",q:"Namanganda har yili gullar festivali o‘tkaziladi.",a:true,e:"Namangan — gullar shahri."},
 {t:"tf",q:"Savitskiy nomidagi mashhur muzey Buxoroda joylashgan.",a:false,e:"Noto‘g‘ri. Savitskiy muzeyi Nukusda."},
 {t:"f",q:"Siz yashaydigan hudud nimasi bilan mashhur?",e:"Masalan: tarixiy obidalar, hunarmandchilik, mevalar, taniqli insonlar yoki tabiat go‘zalligi."}]},
{id:"m18",n:"18-mavzu",t:"Muzeylar — moziy ko‘zgusi",b:4,
 map:{c:"Muzeylar",br:[
  {t:"Muzey nima?",e:"🏛️",k:["yunoncha so‘z","moziy","osori atiqa"],x:"Muzeyda ajdodlar hayoti va urf-odatlarini aks ettiruvchi qadimiy buyumlar saqlanadi."},
  {t:"Eksponat",e:"🖼️",k:["tomosha","san’at asari","hujjat"],x:"Eksponat — tomosha uchun muzey yoki ko‘rgazmaga qo‘yilgan buyum."},
  {t:"Tartib-qoida",e:"📵",k:["suratga olmaslik","ehtiyot","jamoat joyi"],x:"Chiroq eski suratlar rangini o‘chirishi mumkin, shuning uchun ba’zi muzeylarda suratga olish taqiqlanadi."},
  {t:"Muzey xodimlari",e:"🧑‍🔬",k:["posbon","ta’mirchi","gid"],x:"Posbon qo‘riqlaydi, ilmiy xodim tadqiq qiladi, ta’mirchi tiklaydi, gid so‘zlab beradi."},
  {t:"Mashhur muzeylar",e:"⭐",k:["San’at muzeyi","Orol muzeyi","Ark qal’asi"],x:"Toshkentdagi san’at muzeyi, Mo‘ynoqdagi Orol tarixi muzeyi, Buxorodagi Ark — mashhur maskanlar."}]},
 q:[
 {t:"m",q:"«Muzey» so‘zi qaysi tildan olingan?",a:["Qadimgi yunon tilidan","Hozirgi ingliz tilidan","Yapon tilidan","Koreys tilidan"],e:"U «ijod, go‘zallik, san’at maskani» degan ma’noni bildiradi."},
 {t:"m",q:"Tomosha uchun muzeyga qo‘yilgan buyum nima deyiladi?",a:["Eksponat","Valyuta","Xumdon","Kollaj"],e:"Eksponat — ko‘pchilik ko‘rishi uchun qo‘yilgan buyum."},
 {t:"m",q:"Mehmonlarga eksponatlar haqida kim so‘zlab beradi?",a:["Gid","Posbon","Ta’mirchi","Kulol"],e:"Gidlar mehmonlarga eksponatlar haqida so‘zlab beradi."},
 {t:"m",q:"Ta’mirchilar muzeyda nima qiladi?",a:["Shikastlangan eksponatlarni tiklaydi","Eshik oldida chipta sotib o‘tiradi","Mehmonlarga ovqat pishirib beradi","Eski buyumlarni axlatga tashlaydi"],e:"Ta’mirchilar shikastlangan eksponatlarni butlaydi va tiklaydi."},
 {t:"m",q:"Ba’zi muzeylarda nega suratga olish taqiqlanadi?",a:["Chiroq eski suratlar rangini o‘chirishi mumkin","Telefonda olingan surat muzeyda umuman chiqmaydi","Suratga olsa, muzey eshiklari o‘zi yopilib qoladi","Mehmonlar eksponatlarni eslab qolmasligi kerak"],e:"Telefon yoki fotoapparat chirog‘i vaqt o‘tishi bilan rangga zarar yetkazadi."},
 {t:"m",q:"Orol dengizi tarixi muzeyi qayerda joylashgan?",a:["Mo‘ynoqda","Buxoroda","Shahrisabzda","Namanganda"],e:"Muzeyga 1984-yilda Mo‘ynoq tumanida O‘rinboy Eskirkepov asos solgan."},
 {t:"m",q:"Afsonaga ko‘ra, Ark qal’asini kim qurgan?",a:["Siyovush","Marko Polo","Bobur","Konfutsiy"],e:"Siyovush buqa terisidan tasmalar kesib, aylana ichiga Arkni qurgan, deyishadi."},
 {t:"tf",q:"Muzeylar tariximizni bilish va keyingi avlodlarga yetkazish uchun kerak.",a:true,e:"Muzeyga borgan odam tarix haqida aniq tasavvur oladi."},
 {t:"tf",q:"Muzeydagi eksponatlarni xohlagancha ushlab, o‘ynash mumkin.",a:false,e:"Noto‘g‘ri. Qadimiy buyumlar nozik, muzey qoidalariga rioya qilib, ehtiyot bo‘lish kerak."},
 {t:"f",q:"Muzeyda qaysi tartib-qoidalarga rioya qilish kerak?",e:"Masalan: eksponatlarga tegmaslik, shovqin qilmaslik, taqiqlangan joyda suratga olmaslik, gidni tinglash."}]},
{id:"m19",n:"19-mavzu",t:"O‘zbekiston bo‘ylab sayohat",b:4,
 map:{c:"Yurtim bo‘ylab",br:[
  {t:"Mashhur shaharlar",e:"🧳",k:["Samarqand","Buxoro","Xiva"],x:"Bu eng mashhur va qadimiy shaharlarga butun dunyodan sayyohlar keladi."},
  {t:"Qadimiy joylar",e:"🏰",k:["Ayozqal’a","Qirqqiz","Xonbandi"],x:"Qizilqum chetida Ayozqal’a, Termizda Qirqqiz, Forish yonida qadimiy Xonbandi to‘g‘oni bor."},
  {t:"Qiziq tabiat",e:"⛰️",k:["Borsakelmas","Qoratepa","Miraki"],x:"Borsakelmas ko‘li, Qoratepa tog‘i, Miraki tog‘lari va Aydarko‘l diqqatga sazovor."},
  {t:"Qo‘riqxonalar",e:"🦌",k:["Hisor","Nurota","Zarafshon"],x:"Qo‘riqxonalar tabiatni, hayvonot va o‘simlik olamini muhofaza qiladi."},
  {t:"Qizil kitob",e:"📕",k:["noyob hayvon","kamayish","asrash"],x:"Yo‘qolib yoki kamayib borayotgan noyob hayvonlar «Qizil kitob»ga kiritilgan."}]},
 q:[
 {t:"m",q:"Xonbandi nima?",a:["Qadimiy to‘g‘on","Tuzli ko‘l","Baland saroy","Tog‘li qo‘riqxona"],e:"Xonbandi — Forish shahri yonidagi ming yil oldin qurilgan to‘g‘on."},
 {t:"m",q:"Suv o‘rniga tuzda cho‘milsa bo‘ladigan ko‘l qaysi?",a:["Borsakelmas","Aydarko‘l","Orol dengizi","Qulasa"],e:"Bolalardan biri Borsakelmas ko‘li haqida shunday aytdi."},
 {t:"m",q:"Baday-To‘qay qo‘riqxonasida qaysi jonivorlar yashashi aytilgan?",a:["Bug‘ular","Pingvinlar","Oq ayiqlar","Delfinlar"],e:"Amudaryodagi Baday-To‘qayda bug‘ular yashaydi."},
 {t:"m",q:"Amir Temur Shohruxiya shahrini kimning nomi bilan atagan?",a:["O‘g‘lining","Ustozining","Do‘stining","Bobosining"],e:"Shaharni qurdirib, o‘g‘lining nomi bilan atagan."},
 {t:"m",q:"Qo‘riqxonalar nima maqsadda tashkil qilinadi?",a:["Tabiatni va jonivorlarni muhofaza qilish","Daraxtlarni kesib, taxta tayyorlab sotish","Noyob hayvonlarni ovlab, sonini kamaytirish","Yangi zavod va katta fabrikalar qurib chiqish"],e:"Maqsad — atrof-muhit, hayvonot va o‘simlik olamini muhofaza qilish."},
 {t:"m",q:"Kamayib borayotgan noyob hayvonlar qaysi kitobga kiritiladi?",a:["«Qizil kitob»","«O‘zbek palovi»","«Ko‘k daftar»","Rekordlar kitobi"],e:"Ular «Qizil kitob»ga kiritilgan va davlat ularni asraydi."},
 {t:"m",q:"Quyidagilardan qaysi biri qo‘riqxona?",a:["Hisor","Registon","Minorayi Kalon","Labi Hovuz"],e:"Eng katta qo‘riqxonalardan: Hisor, Nurota va Zarafshon."},
 {t:"tf",q:"O‘zbekistondagi ko‘p obyektlar UNESKOning Butunjahon merosi ro‘yxatiga kiritilgan.",a:true,e:"Darslikda shunday deyilgan."},
 {t:"tf",q:"Lola ko‘rsatgan Xonbandiga juda ko‘p odam borgan ekan.",a:false,e:"Yo‘q. Akasining aytishicha, u yerga juda kam odam borgan."},
 {t:"f",q:"O‘zbekistonning qaysi joyiga sayohat qilishni xohlaysiz va nega?",e:"Masalan: Samarqand, Xiva, Mo‘ynoq yoki tog‘lar — tarixi va go‘zal tabiatini o‘z ko‘zim bilan ko‘rish uchun."}]}
);
